Definition pf_lows5 (sp : word) (B E : Z) : list cell :=
  [C8 (wz 4095); C8 (Z_to_bv 64 (bv_unsigned sp + 184)); C8 (wz (B + 8)); C8 (wz (E + 16)); C8 (shw (E + 16))].

Definition pf_fctx (m m1 : mem) (sp : word) (SV : list cell) (B E L lo shi : Z) (p0 : Z) (bs : list byte)
    (tlc tmp : list cell) (pv nlen : Z) (vlc : list cell) (bsz : Z) (bb : list byte) (ecs : list cell) (g : bool) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -176) (pf_lows5 sp B E)
  /\ rw_cells asegs m1 (bv_unsigned sp + -136) tlc
  /\ rw_cells asegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells asegs m1 (bv_unsigned sp + -104) SV
  /\ rw_cells asegs m1 (bv_unsigned sp + 176) [C8 (wz pv)]
  /\ rw_cells asegs m1 (bv_unsigned sp + 200) [C8 (wz p0); C8 (wz nlen)]
  /\ rw_cells asegs m1 (bv_unsigned sp + 184) vlc
  /\ rw_cells asegs m1 B [C8 (wz bsz)]
  /\ u8arr asegs m1 (B + 8) bb /\ length bb = 4096%nat
  /\ rw_cells asegs m1 E ecs
  /\ bytes_at asegs m1 p0 bs /\ L = p0 + Z.of_nat (length bs) /\ APfTab m1
  /\ AHttpCat m1 g
  /\ stk asegs m1 lo (bv_unsigned sp + -176)
  /\ munch (pf_W lo sp B E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ pf_side m B E p0 (Z.of_nat (length bs)) lo shi.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.

Lemma pf_fctx_ctx : forall m m1 sp SV B E L lo shi p0 bs (tw : word) tmp pv nlen vlc bsz bb ecs g,
  pf_fctx m m1 sp SV B E L lo shi p0 bs [C8 tw] tmp pv nlen vlc bsz bb ecs g ->
  pf_ctx m m1 sp SV B E L lo shi p0 bs (pf_lows (wz 4095) (Z_to_bv 64 (bv_unsigned sp + 184)) (wz (B + 8)) E tw) tmp pv
         [C8 (wz p0); C8 (wz nlen)] vlc bsz bb ecs g.
