Lemma pf_trim6 : forall (k : nat) (t : Z)
    rax spx gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s8 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (p0 p : Z) (bs : list byte),
  bytes_at asegs m1 p0 bs -> accessible m1 p0 (Z.of_nat (length bs)) ->
