Definition PF_L6_AT (M : Z) : Prop :=
  forall (p : Z) rax ra sp gp tp t0 t1 t2 a1 a2 a3 a5 a6 a7 s6x t3x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (B E L lo shi : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (tlc tmp : list cell) (nlen : Z) (vlc : list cell) (bsz : Z) (bb : list byte) (g : bool),
  pf_fctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) B E L lo shi p0 bs
          tlc tmp p nlen vlc bsz bb (ErrCodeCells E0) g ->
  pf_pure sp B E lo shi p0 bs E0 -> 0 <= bsz <= 4096 -> cells_size tlc = 8%nat -> cells_size tmp = 24%nat -> cells_size vlc = 16%nat ->
  p + 1 <= L -> p0 + 2 <= p -> 1 <= nlen -> p0 + nlen < p -> bsz + nlen + 3 <= p - p0 -> L - p < M ->
  evt asegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc B E lo shi p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -176)) gp tp t0 t1 t2 (wz E) (shw B) (wz (p + 1)) a1 a2 a3 (wz B) a5 a6 a7
              (wz 32) (wz (E + 16)) (Z_to_bv 64 (bv_unsigned sp + 176)) (wz L) s6x (wz p) (shw (E + 16)) (wz 2147450880) (wz 9)
              (shw (bv_unsigned sp + 176)) t3x t4 t5 t6)
        F (Z_to_bv 64 0xd1368) fc None m1 (seg_rom asegs)).

